1→//! Minimal admin CLI for the op-cognitive cozo store.
//!
//! Examples:
//!   op-cog-admin --db /var/lib/op-dbus/cognitive.db user-add <wg_pubkey>
//!   op-cog-admin --db /var/lib/op-dbus/cognitive.db user-list

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use op_cozo_store::CozoGraphShuttle;
10→use std::path::PathBuf;

#[derive(Parser)]
#[command(name = "op-cog-admin", about = "Cozo store admin for op-cognitive")]
struct Cli {
    #[arg(
        long,
        env = "COGNITIVE_DB_PATH",
        default_value = "/var/lib/op-dbus/cognitive.db"
    )]
20→    db: String,
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// Insert or refresh a user keyed by wg_pubkey
    UserAdd { wg_pubkey: String },
    /// List all users
30→    UserList,
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    let shuttle = CozoGraphShuttle::new_persistent(PathBuf::from(&cli.db))
        .with_context(|| format!("opening cozo at {}", cli.db))?;

    match cli.cmd {
        Cmd::UserAdd { wg_pubkey } => {
40→            shuttle.upsert_user(&wg_pubkey)?;
            println!("ok: user {} upserted", wg_pubkey);
        }
        Cmd::UserList => {
            let json = shuttle.run_query(
                "?[wg_pubkey, created_at] := *users[wg_pubkey, created_at]",
                None,
            )?;
            println!("{}", serde_json::to_string_pretty(&json)?);
        }
50→    }
    Ok(())
}

1→//! Receive hook for vector-dump replication: index received vectors and chain links.
//!
//! Invoked as `exec <program> <received-path> <stream-uuid>` (no subcommand).

use anyhow::{Context, Result};
use op_cognitive::ChainVectorIndex;
use std::path::PathBuf;

#[tokio::main]
10→async fn main() -> Result<()> {
    let received_path = std::env::args()
        .nth(1)
        .context("missing received path argument")?;
    let stream_uuid = std::env::args()
        .nth(2)
        .context("missing stream uuid argument")?;
    anyhow::ensure!(!stream_uuid.is_empty(), "stream uuid must be non-empty");

    let received = PathBuf::from(&received_path);
20→    let root = received
        .parent()
        .context("received path has no parent directory")?;

    let index = ChainVectorIndex::open_received_root(root).await?;
    index.ingest_received(None).await?;
    Ok(())
}

1→// Compatibility gate for embedded CognitiveToolService consumers. The active
// external MCP gateway and its authentication policy live in op-grpc-bridge.
// Authentication here resolves one projected session and verifies the request's
// genesis against that record.

use op_identity::SessionGenesisVerifyError;
use tonic::{Request, Status};

/// Identity extracted by the Ghostbridge interceptor and attached to each
10→/// accepted request for downstream authorization / trace linking.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GhostbridgeIdentity {
    pub principal_id: String,
    pub session_id: String,
    pub session_genesis: String,
}

#[allow(clippy::result_large_err)]
pub fn ghostbridge_interceptor(mut req: Request<()>) -> Result<Request<()>, Status> {
20→    let genesis_value = req.metadata().get("x-ghostbridge-genesis").cloned();
    let trace_value = req.metadata().get("x-ghostbridge-trace-id").cloned();
    let pubkey_value = req.metadata().get("x-wireguard-pubkey").cloned();

    if genesis_value.is_none() || (trace_value.is_none() && pubkey_value.is_none()) {
        return Err(Status::unauthenticated(
            "Missing Ghostbridge session identity.",
        ));
    }

30→    let request_genesis = genesis_value
        .as_ref()
        .unwrap()
        .to_str()
        .map_err(|_| Status::invalid_argument("Invalid genesis header encoding"))?;
    let trace_id = trace_value.as_ref().and_then(|value| value.to_str().ok());
    let wireguard_pubkey = pubkey_value.as_ref().and_then(|value| value.to_str().ok());

    let identity =
        op_identity::resolve_verified_session(request_genesis, trace_id, wireguard_pubkey)
40→            .map_err(|error| match error {
                SessionGenesisVerifyError::SledUnreachable => {
                    Status::internal("Identity session projection unreachable")
                }
                SessionGenesisVerifyError::InvalidSled => {
                    Status::failed_precondition("Identity session is not anchored")
                }
                SessionGenesisVerifyError::Inactive => {
                    Status::permission_denied("Identity session is inactive")
                }
50→                SessionGenesisVerifyError::Expired => {
                    Status::permission_denied("Identity session term has expired")
                }
                SessionGenesisVerifyError::Mismatch => Status::permission_denied(
                    "Session genesis does not match the projected identity record.",
                ),
            })?;

    req.extensions_mut().insert(GhostbridgeIdentity {
        principal_id: op_identity::session::derive_principal_id(&identity.wireguard_pubkey),
60→        session_id: identity.session_id,
        session_genesis: request_genesis.to_string(),
    });

    Ok(req)
}

