1→//! D-Bus interface for the Cognitive tool registry.
//!
//! service:   org.opdbus.v1.plugins
//! object:    /org/opdbus/v1/plugins/cognitive
//! interface: org.opdbus.v1.plugins.Cognitive
//!
//! Methods:
//!   ListTools() -> s                  JSON array [{name, description, category}]
//!   GetToolSchema(s name) -> s        JSON input schema, or "null"
10→//!   CallTool(s name, s args_json) -> s  JSON result, or {"error":"..."}

use op_mcp::tool_registry::ToolRegistry;
